records.formula:
for each key K and each V in map[ K ]:
  completed[ V ] = completed[ V ] + [ K ]   when V is already a key and K ∉ completed[ V ]
  completed[ V ] = [ K ]                    otherwise

selected_lots = { lots : alert_date ≤ today and reminded_flag = false }
lots_with_an_activity = { lots of selected_lots : at least one quant with quantity > 0 in an internal location }
lots_marked_as_reminded = selected_lots      ( the whole selection, not only those that received an activity )
